export const WORLD={w:1100,h:720};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
export class PackDemo{
 constructor(random=Math.random){this.random=random;this.reset()}
 reset(){this.player={x:550,y:360,hp:100,angle:0};this.state='ready';this.time=0;this.charge=0;this.spraying=0;this.equipped=true;this.enemies=[];this.water=[];this.sparks=[];this.kills=0;this.waterKills=0;this.bursts=0;this.waterDamage=0;this.nextId=0;this.spawnClock=.3;this.waterClock=0;this.hurt=0;this.flash=0;this.firing=false;this.message='朝前喷火，水包会收集燃烧生成的水。';for(let i=0;i<7;i++)this.spawn()}
 start(){if(this.state==='ready')this.state='playing'}
 togglePack(){this.equipped=!this.equipped;this.charge=0;this.spraying=0;this.message=this.equipped?'空水包已装上。继续喷火，看看背后会发生什么。':'水包已拆下：火焰照常攻击，水蒸气直接散去。'}
 spawn(){const a=this.random()*Math.PI*2,r=270+this.random()*180;const fast=this.random()<.28;this.enemies.push({id:++this.nextId,x:clamp(this.player.x+Math.cos(a)*r,20,WORLD.w-20),y:clamp(this.player.y+Math.sin(a)*r,20,WORLD.h-20),hp:fast?27:42,maxHp:fast?27:42,r:fast?12:17,speed:fast?61:35,burn:0,hit:0,type:fast?'metal':'colloid'})}
 waterAngle(){const p=this.player;let best=null,dist=Infinity;for(const e of this.enemies){const a=Math.atan2(e.y-p.y,e.x-p.x),d=Math.hypot(e.x-p.x,e.y-p.y);if(e.hp>0&&Math.abs(angleDiff(a,p.angle))>Math.PI/3&&d<dist){best=a;dist=d}}return best??p.angle+Math.PI}
 step(dt,input={}){if(this.state!=='playing')return;dt=clamp(dt,0,.04);this.time+=dt;this.hurt=Math.max(0,this.hurt-dt);this.flash=Math.max(0,this.flash-dt);const p=this.player,m=Math.hypot(input.x||0,input.y||0);if(m){p.x=clamp(p.x+(input.x||0)/Math.max(1,m)*180*dt,24,WORLD.w-24);p.y=clamp(p.y+(input.y||0)/Math.max(1,m)*180*dt,24,WORLD.h-24)}
 const nearest=this.enemies.filter(e=>e.hp>0).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(input.aim)p.angle=Math.atan2(input.aim.y-p.y,input.aim.x-p.x);else if(nearest)p.angle=Math.atan2(nearest.y-p.y,nearest.x-p.x);this.firing=input.fire!==false;
 if(this.firing){for(const e of this.enemies){const d=Math.hypot(e.x-p.x,e.y-p.y),a=Math.atan2(e.y-p.y,e.x-p.x);if(d<190+e.r&&Math.abs(angleDiff(a,p.angle))<.5){e.hp-=33*dt;e.burn=1.6;e.hit=.08}}}
 if(this.equipped){if(this.spraying>0){this.charge=Math.max(0,this.charge-dt/1.8+(this.firing?dt/5:0));this.waterClock-=dt;if(this.waterClock<=0){this.waterClock=.045;const a=this.waterAngle();for(const spread of [-.07,.07]){const angle=a+spread;this.water.push({x:p.x-Math.cos(p.angle)*15,y:p.y-Math.sin(p.angle)*15,vx:Math.cos(angle)*510,vy:Math.sin(angle)*510,life:.64,hitIds:new Set()})}}if(this.charge===0){this.spraying=0;this.message='水包已空，喷水停止。继续喷火，蓄满后再次启动！'}}else if(this.firing){this.charge=Math.min(1,this.charge+dt/5);if(this.charge>=1){this.spraying=1;this.waterClock=0;this.bursts++;this.flash=.5;this.message='蓄满！水包自动向侧后方喷水，主枪继续喷火。'}}}
 for(const w of this.water){const ox=w.x,oy=w.y;w.x+=w.vx*dt;w.y+=w.vy*dt;w.life-=dt;for(const e of this.enemies){if(e.hp<=0||w.hitIds.has(e.id))continue;const dx=w.x-ox,dy=w.y-oy,q=clamp(((e.x-ox)*dx+(e.y-oy)*dy)/(dx*dx+dy*dy||1),0,1);if(Math.hypot(e.x-ox-q*dx,e.y-oy-q*dy)<e.r+7){w.hitIds.add(e.id);e.hp-=8;e.hit=.15;this.waterDamage+=8;e.x=clamp(e.x+w.vx*.022,e.r,WORLD.w-e.r);e.y=clamp(e.y+w.vy*.022,e.r,WORLD.h-e.r);if(e.hp<=0)this.waterKills++;this.sparks.push({x:e.x,y:e.y,life:.35,kind:'water'})}}}this.water=this.water.filter(w=>w.life>0&&w.x>0&&w.x<WORLD.w&&w.y>0&&w.y<WORLD.h);
 for(const e of this.enemies){if(e.hp<=0)continue;if(e.burn>0){e.burn=Math.max(0,e.burn-dt);e.hp-=7*dt}e.hit=Math.max(0,e.hit-dt);if(e.hp<=0)continue;const dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;e.x=clamp(e.x+dx/d*e.speed*dt,e.r,WORLD.w-e.r);e.y=clamp(e.y+dy/d*e.speed*dt,e.r,WORLD.h-e.r);if(d<e.r+17&&this.hurt===0){p.hp=Math.max(0,p.hp-8);this.hurt=.65}}
 const dead=this.enemies.filter(e=>e.hp<=0);this.kills+=dead.length;for(const e of dead)this.sparks.push({x:e.x,y:e.y,life:.45,kind:'kill'});this.enemies=this.enemies.filter(e=>e.hp>0);for(const s of this.sparks)s.life-=dt;this.sparks=this.sparks.filter(s=>s.life>0);this.spawnClock-=dt;if(this.spawnClock<=0){this.spawnClock=Math.max(.32,.9-this.time*.007);if(this.enemies.length<45)this.spawn()}
 if(p.hp<=0){this.state='dead';this.firing=false}else if(this.time>=60){this.state='won';this.firing=false}
 }
}
